package studio.jiayu.neoagent;
import android.content.Context;import org.json.*;import java.util.*;
/** Remember routine control consent by recipient and explicitly selected applications. */
final class RoutineAccess {
 static final String KEY="routine-control-consent-v1";final Context context;
 RoutineAccess(Context c){context=c;}
 JSONArray records()throws Exception{String raw=new Vault(context).get(KEY);if(raw.isEmpty())return new JSONArray();JSONObject saved=new JSONObject(raw);return saved.has("grants")?saved.getJSONArray("grants"):new JSONArray().put(saved);}
 void approve(Config config,Collection<String> apps)throws Exception{config.validate();JSONArray records=records(),allowed=new JSONArray(),next=new JSONArray();LinkedHashSet<String> packages=new LinkedHashSet<>();AppAccess access=new AppAccess(context);boolean vision=config.vision;for(String pkg:apps){access.require(pkg);packages.add(pkg);}for(int i=0;i<records.length();i++){JSONObject previous=records.getJSONObject(i);if(config.endpoint.equals(previous.optString("endpoint"))&&"full_target_app_v1".equals(previous.optString("visual_scope"))){vision|=previous.optBoolean("vision");JSONArray old=previous.optJSONArray("apps");if(old!=null)for(int j=0;j<old.length();j++)if(access.allowed(old.getString(j)))packages.add(old.getString(j));}else next.put(previous);}for(String pkg:packages)allowed.put(pkg);next.put(new JSONObject().put("endpoint",config.endpoint).put("visual_scope","full_target_app_v1").put("vision",vision).put("apps",allowed));while(next.length()>16)next.remove(0);new Vault(context).put(KEY,new JSONObject().put("grants",next).toString());}
 boolean allows(Config config,Collection<String> apps){try{JSONArray all=records();if(apps.isEmpty())return false;for(int index=0;index<all.length();index++){JSONObject grant=all.getJSONObject(index);if(!"full_target_app_v1".equals(grant.optString("visual_scope"))||!config.endpoint.equals(grant.optString("endpoint"))||config.vision&&!grant.optBoolean("vision"))continue;JSONArray saved=grant.getJSONArray("apps");boolean matched=true;for(String pkg:apps){new AppAccess(context).require(pkg);boolean found=false;for(int i=0;i<saved.length();i++)if(pkg.equals(saved.getString(i)))found=true;if(!found)matched=false;}if(matched)return true;}return false;}catch(Exception ignored){return false;}}
}
